<script>
(function(){
var root=document.getElementById('chasStudio');if(!root||root.dataset.ready)return;root.dataset.ready='1';
var s={skin:'#F6D0B1',hair:'#30243A',bg:'#EDE9FE',shirt:'#6257D9',eyes:'round',hairStyle:'wave',outfit:'classic',accessory:'none',face:'soft'};
var defaults=JSON.parse(JSON.stringify(s));
function el(tag,attrs,inner){var n=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.keys(attrs||{}).forEach(function(k){n.setAttribute(k,attrs[k]);});if(inner)n.innerHTML=inner;return n;}
function render(){
var skin=s.skin,hair=s.hair,bg=s.bg,shirt=s.shirt;
var hairBack=s.hairStyle==='long'?'<path d="M93 139 Q72 44 180 44 Q288 44 267 140 L255 260 Q230 286 221 205 L139 205 Q130 280 105 260Z" fill="'+hair+'"/>':'';
var top=s.hairStyle==='short'?'<path d="M96 123 Q72 46 180 47 Q279 45 264 125 L238 103 Q216 67 178 78 Q137 67 112 111Z" fill="'+hair+'"/>':s.hairStyle==='curl'?'<path d="M94 127 Q64 82 105 66 Q104 31 144 49 Q173 20 196 48 Q237 28 249 66 Q291 80 264 130 L239 102 Q211 70 179 77 Q139 70 113 111Z" fill="'+hair+'"/>':'<path d="M94 128 Q73 47 180 45 Q282 43 266 130 L239 103 Q219 65 179 76 Q140 68 112 111Z" fill="'+hair+'"/>';
var eye=s.eyes==='happy'?'<path d="M133 139 q10 9 20 0 M207 139 q10 9 20 0" fill="none" stroke="#48352F" stroke-width="5" stroke-linecap="round"/>':s.eyes==='soft'?'<ellipse cx="143" cy="139" rx="7" ry="9" fill="#48352F"/><ellipse cx="217" cy="139" rx="7" ry="9" fill="#48352F"/>':'<ellipse cx="143" cy="139" rx="8" ry="10" fill="#48352F"/><ellipse cx="217" cy="139" rx="8" ry="10" fill="#48352F"/><circle cx="145" cy="136" r="2.5" fill="#fff"/><circle cx="219" cy="136" r="2.5" fill="#fff"/>';
var accessory=s.accessory==='glasses'?'<g fill="none" stroke="#443b66" stroke-width="5"><rect x="119" y="124" width="45" height="31" rx="11"/><rect x="196" y="124" width="45" height="31" rx="11"/><path d="M164 135 Q180 127 196 135"/></g>':s.accessory==='earrings'?'<g fill="#F6D36B" stroke="#fff" stroke-width="2"><circle cx="106" cy="164" r="7"/><circle cx="254" cy="164" r="7"/></g>':s.accessory==='cap'?'<g><path d="M94 99 Q106 46 179 47 Q244 46 263 99Z" fill="#E8B64F"/><path d="M166 98 Q220 88 274 107 Q224 126 166 108Z" fill="#D59A2D"/></g>':'';
var faceRx=s.face==='round'?60:s.face==='sharp'?48:54;
var svg='<svg xmlns="http://www.w3.org/2000/svg" width="360" height="360" viewBox="0 0 360 360"><defs><linearGradient id="shirtG" x1="0" y1="0" x2="1" y2="1"><stop stop-color="'+shirt+'"/><stop offset="1" stop-color="'+shirt+'" stop-opacity=".78"/></linearGradient><clipPath id="clip"><rect width="360" height="360" rx="28"/></clipPath></defs><g clip-path="url(#clip)"><rect width="360" height="360" fill="'+bg+'"/><circle cx="180" cy="166" r="121" fill="#ffffff" opacity=".48"/><circle cx="54" cy="72" r="7" fill="#fff" opacity=".8"/><circle cx="299" cy="92" r="5" fill="#fff" opacity=".9"/><path d="M64 360 Q67 263 131 253 L229 253 Q293 267 296 360Z" fill="url(#shirtG)"/><path d="M147 244 L147 277 Q180 303 213 277 L213 244Z" fill="'+skin+'"/>'+hairBack+'<ellipse cx="104" cy="163" rx="13" ry="20" fill="'+skin+'"/><ellipse cx="256" cy="163" rx="13" ry="20" fill="'+skin+'"/><path d="M180 74 Q118 74 117 133 L121 180 Q124 230 180 250 Q236 230 239 180 L243 133 Q242 74 180 74Z" fill="'+skin+'"/>'+top+'<path d="M122 169 Q132 183 151 178" fill="none" stroke="#D99D7D" stroke-width="3" stroke-linecap="round" opacity=".6"/><path d="M209 178 Q228 183 238 169" fill="none" stroke="#D99D7D" stroke-width="3" stroke-linecap="round" opacity=".6"/>'+eye+'<path d="M180 143 Q173 164 179 171" fill="none" stroke="#D69A79" stroke-width="4" stroke-linecap="round"/><path d="M157 195 Q180 210 203 195 Q182 224 157 195Z" fill="#B85E69"/><path d="M157 195 Q180 201 203 195" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"/><ellipse cx="142" cy="178" rx="14" ry="7" fill="#EF8D8B" opacity=".23"/><ellipse cx="218" cy="178" rx="14" ry="7" fill="#EF8D8B" opacity=".23"/>'+accessory+'<path d="M141 259 L180 288 L219 259" fill="none" stroke="#ffffff" stroke-opacity=".55" stroke-width="4"/><circle cx="180" cy="304" r="5" fill="#F8D77B"/><path d="M45 292 l5 12 12 5 -12 5 -5 12 -5 -12 -12 -5 12 -5Z" fill="#fff" opacity=".65"/><path d="M302 240 l4 9 9 4 -9 4 -4 9 -4 -9 -9 -4 9 -4Z" fill="#fff" opacity=".75"/></g></svg>';
root.querySelector('#chasAvatar').innerHTML=svg;
}
function select(container,button){container.querySelectorAll('button').forEach(function(b){b.classList.toggle('selected',b===button);});}
root.querySelectorAll('[data-key]').forEach(function(group){group.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){s[group.dataset.key]=b.dataset.value;select(group,b);render();});});});
root.querySelectorAll('.chas-tab').forEach(function(b){b.addEventListener('click',function(){root.querySelectorAll('.chas-tab').forEach(function(t){t.classList.toggle('active',t===b);});root.querySelectorAll('.chas-panel').forEach(function(p){p.classList.toggle('active',p.dataset.panel===b.dataset.tab);});root.querySelector('.chas-step').innerHTML=String(Array.prototype.indexOf.call(root.querySelectorAll('.chas-tab'),b)+1).padStart(2,'0')+' <i>/</i> 04';});});
function sync(){root.querySelectorAll('[data-key]').forEach(function(g){g.querySelectorAll('button').forEach(function(b){b.classList.toggle('selected',s[g.dataset.key]===b.dataset.value);});});render();}
root.querySelector('#chasReset').addEventListener('click',function(){s=JSON.parse(JSON.stringify(defaults));sync();});
root.querySelector('#chasRandom').addEventListener('click',function(){root.querySelectorAll('[data-key]').forEach(function(g){var choices=g.querySelectorAll('button');var b=choices[Math.floor(Math.random()*choices.length)];if(b)s[g.dataset.key]=b.dataset.value;});sync();});
function message(txt,kind){var m=root.querySelector('#chasMessage');m.textContent=txt;m.className='chas-message '+(kind||'');}
root.querySelector('#chasSave').addEventListener('click',function(){
var btn=this;btn.disabled=true;message('Je ontwerp wordt opgeslagen…');
var svg=root.querySelector('#chasAvatar svg').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');
var xml=new XMLSerializer().serializeToString(svg);var url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml;charset=utf-8'}));var img=new Image();
img.onload=function(){try{var c=document.createElement('canvas');c.width=360;c.height=360;var ctx=c.getContext('2d');ctx.drawImage(img,0,0,360,360);URL.revokeObjectURL(url);c.toBlob(function(blob){if(!blob){btn.disabled=false;message('Afbeelding kon niet worden gemaakt.','error');return;}var reader=new FileReader();reader.onload=function(){var fd=new FormData();fd.append('action','save_avatar');fd.append('image',reader.result);fetch('<?php echo htmlspecialchars($actionUrl, ENT_QUOTES, 'UTF-8'); ?>',{method:'POST',body:fd,credentials:'same-origin'}).then(function(r){return r.json();}).then(function(r){btn.disabled=false;message(r.message||'Klaar.',r.ok?'success':'error');if(r.ok)setTimeout(function(){window.location.reload();},1100);}).catch(function(){btn.disabled=false;message('Serverantwoord niet leesbaar. Controleer de CodyChat addon-installatie.','error');});};reader.readAsDataURL(blob);},'image/png');}catch(e){btn.disabled=false;message('De avatar kon niet worden voorbereid.','error');}};
img.onerror=function(){URL.revokeObjectURL(url);btn.disabled=false;message('Preview exporteren is mislukt.','error');};img.src=url;
});
root.querySelector('#chasRestore').addEventListener('click',function(){if(!window.confirm('Wil je je eerder opgeslagen avatar terugzetten?'))return;fetch('<?php echo htmlspecialchars($restoreUrl, ENT_QUOTES, 'UTF-8'); ?>',{method:'POST',credentials:'same-origin'}).then(function(r){return r.json();}).then(function(r){message(r.message||'Klaar.',r.ok?'success':'error');if(r.ok)setTimeout(function(){window.location.reload();},1000);}).catch(function(){message('Herstellen is mislukt.','error');});});
render();
})();
</script>
